const ctx = $('Montar prompt do porteiro').item.json;
const cru = $json.output === undefined ? $json : $json.output;

let enviar = typeof cru.enviar === 'boolean' ? cru.enviar : true;
let motivo = String(cru.motivo ?? '').trim().slice(0, 400);
let quando = String(cru.reagendar_para ?? '').trim();

if (enviar) quando = '';

if (quando && !/^\d{4}-\d{2}-\d{2} \d{2}:\d{2}$/.test(quando)) quando = '';
if (quando) {
  if (quando < ctx.minimo_local) quando = ctx.minimo_local;
  if (quando > ctx.limite_local) quando = ctx.limite_local;
}

if (!enviar && !motivo) motivo = 'o porteiro barrou sem dizer o motivo';

return {
  json: {
    ...ctx,
    enviar,
    motivo_porteiro: motivo,
    reagendar_para: quando,
    tem_reagendamento: quando !== "",
  },
};

const d = $input.item.json;

const rotulo = (q) => (q === "lead" ? "LEAD" : q === "equipe" ? "EQUIPE" : "IA");
const hist = Array.isArray(d.historico) ? d.historico : [];
const conversa = hist.length
  ? hist.map((m) => "[" + m.em + "] " + rotulo(m.quem) + ": " + m.texto).join("\n")
  : "(sem mensagens)";

const antes = Array.isArray(d.textos_anteriores) ? d.textos_anteriores : [];
const anteriores = antes.length
  ? antes.map((t) => "[" + t.em + "] (" + t.tipo + ") " + t.texto).join("\n")
  : "(nenhum ainda, este e o primeiro toque)";

// Primeiro nome so: "isadora" soa como gente, "isadora souza" soa como cadastro.
const atendente = String(d.atendente_nome || "").trim().split(/\s+/)[0] || "a equipe";

// MODO: o piso deterministico entre reabrir a conversa e retomar um assunto
// concreto. Fica em codigo porque deixar o modelo julgar sozinho e o que
// produzia link e oferta em todo texto: escrevendo, ele sempre acha um motivo
// pra empurrar. O prompt pode SUBIR pra RETOMAR se achar o pedido nas
// palavras do proprio lead, e o default de duvida e REABRIR.
// "Link enviado" ficou de fora de proposito: essa etiqueta registra o que a
// EQUIPE fez, nao o que o lead pediu. A equipe manda valor e link logo no
// comeco pra quem so perguntou "como funciona", e promover esse lead a RETOMAR
// era autorizar o modelo a remandar o mesmo link. Se o lead tiver pedido de
// verdade, o proprio prompt sobe o modo pelas palavras dele.
const ETAPAS_CONCRETAS = ["aguardando pagamento", "agendado", "aula realizada"];
const TIPOS_CONCRETOS = ["lembrete_d1", "lembrete_dia", "pos_aula"];
const etiquetaBaixa = String(d.etiqueta || "").trim().toLowerCase();
const temAula = Boolean(d.data_agendada_local);
const tipoConcreto = TIPOS_CONCRETOS.includes(String(d.tipo || ""));
const retomar = temAula || tipoConcreto || ETAPAS_CONCRETAS.includes(etiquetaBaixa);
const modo = retomar ? "RETOMAR" : "REABRIR";
const porqueModo = temAula
  ? "o lead tem aula marcada"
  : tipoConcreto
    ? "follow-up de aula marcada"
    : retomar
      ? "a etapa do funil (" + d.etiqueta + ") mostra pedido concreto"
      : etiquetaBaixa === "link enviado"
        ? "Link enviado registra o que a EQUIPE fez, nao pedido do lead"
        : "a etapa do funil nao mostra nenhum pedido concreto do lead";

// Link ja mandado e fato do historico, entao vem daqui e nao da leitura do
// modelo. Conta tambem o que a EQUIPE mandou na mao: o caso comum e a
// atendente ter despejado valores e link na primeira resposta, e insistir
// nisso e o que fazia o texto soar como cobranca.
const tudoQueJaFoi = hist.concat(antes).map((m) => String(m.texto || "")).join(" ").toLowerCase();
const jaMandados = [];
if (tudoQueJaFoi.includes("wakeclub.com.br/agendar")) jaMandados.push("o link de agendar");
if (tudoQueJaFoi.includes("wakeclub.com.br/carteira")) jaMandados.push("o link da carteira (valores)");
const linhaLinks = jaMandados.length
  ? jaMandados.join(" e ") + " ja esta com o lead. NAO mande de novo."
  : "nenhum ainda";

const ficha = [
  "AGORA: " + d.agora_local + " (America/Sao_Paulo)",
  "VOCE E: " + atendente,
  "MODO: " + modo + " (" + porqueModo + ")",
  "NUMERO DESTE TOQUE: " + (antes.length + 1),
  "LINKS JA MANDADOS: " + linhaLinks,
  "LEAD: " + (d.nome || "sem nome"),
  "ETIQUETA: " + (d.etiqueta || "-"),
  "TEMPERATURA: " + (d.temperatura || "-"),
  "INTERESSE: " + (d.interesse || "-"),
  "OBJECAO QUE TRAVOU: " + (d.objecao || "-"),
  "RESUMO DA CONVERSA: " + (d.resumo || "-"),
  "TOQUES SEM RESPOSTA ATE AGORA: " + (d.n_toques ?? 0),
  "AULA MARCADA PARA: " + (d.data_agendada_local || "nao ha"),
  "",
  "ESTE FOLLOW-UP",
  "  tipo: " + d.tipo,
  "  por que foi agendado: " + (d.motivo || "-"),
].join("\n");

const prompt = ficha +
  "\n\nCONVERSA ATE AQUI:\n" + conversa +
  "\n\nTEXTOS QUE VOCE JA MANDOU NESTE LEAD (nao repita o angulo):\n" + anteriores +
  "\n\nEscreva a mensagem no modo " + modo + ".";

return { json: { ...d, prompt_usuario: prompt, atendente_primeiro_nome: atendente, modo } };

const ctx = $('Montar prompt do redator').item.json;
const cru = $json.output === undefined ? $json : $json.output;

const PERMITIDOS = [
  'https://www.wakeclub.com.br/agendar',
  'https://www.wakeclub.com.br/carteira',
];

let texto = String(cru.texto ?? '').trim();

texto = texto.replace(/(?<!\/\/)\bwww\.[^\s)>\]]+/gi, (u) => 'https://' + u);

texto = texto.replace(/https?:\/\/[^\s)>\]]+/gi, (u) => {
  const limpo = u.replace(/[.,;:!?]+$/, '');
  return PERMITIDOS.includes(limpo.toLowerCase()) ? limpo : '';
});

texto = texto.replace(/[\u{1F000}-\u{1FAFF}\u{2600}-\u{27BF}\u{FE0F}\u{2B00}-\u{2BFF}]/gu, '');
texto = texto.replace(/[—–]/g, ' ');

texto = texto.replace(/[ \t]+/g, ' ').replace(/ ?\n ?/g, '\n').replace(/\n{3,}/g, '\n\n').trim();
if (texto.length > 600) {
  texto = texto.slice(0, 600).replace(/\s+\S*$/, '').trim();
}

// O piso e 10 e nao 20 desde 06/08/2026: no modo REABRIR a mensagem certa e
// uma frase so ("Felipe, ta por ai?" tem 18 caracteres), entao 20 rejeitaria
// exatamente o texto que passamos a querer.
if (texto.length < 10) {
  throw new Error('texto vazio ou curto demais depois da limpeza');
}

return { json: { followup_id: ctx.followup_id, lead_id: ctx.lead_id, texto } };
